import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            while (ptr < len && buffer[ptr] <= ' ') ptr++;
            if (ptr == len) {
                len = in.read(buffer);
                ptr = 0;
            }
            int value = 0;
            while (ptr < len && buffer[ptr] > ' ') {
                value = value * 10 + buffer[ptr++] - '0';
            }
            return value;
        }
    }

    static class MinHeap {
        final int[] heap;
        final int[] position;
        final int[] distance;
        int size = 0;

        MinHeap(int capacity, int[] distance, int[] position) {
            heap = new int[capacity];
            this.distance = distance;
            this.position = position;
        }

        void insertOrDecrease(int node) {
            int p = position[node];
            if (p == -1) {
                p = size++;
                heap[p] = node;
                position[node] = p;
            }
            while (p > 0) {
                int parent = (p - 1) >>> 1;
                if (distance[heap[parent]] <= distance[heap[p]]) break;
                swap(p, parent);
                p = parent;
            }
        }

        int removeMin() {
            int result = heap[0];
            position[result] = -2;
            int last = heap[--size];
            if (size > 0) {
                heap[0] = last;
                position[last] = 0;
                int p = 0;
                while (true) {
                    int left = p * 2 + 1;
                    if (left >= size) break;
                    int right = left + 1;
                    int child = right < size && distance[heap[right]] < distance[heap[left]]
                            ? right : left;
                    if (distance[heap[p]] <= distance[heap[child]]) break;
                    swap(p, child);
                    p = child;
                }
            }
            return result;
        }

        void swap(int a, int b) {
            int x = heap[a];
            heap[a] = heap[b];
            heap[b] = x;
            position[heap[a]] = a;
            position[heap[b]] = b;
        }
    }

