        int target = Arrays.binarySearch(xs, xf) + Arrays.binarySearch(ys, yf) * xCount;

        MinHeap heap = new MinHeap(nodeCount, distance, position);
        distance[start] = 0;
        heap.insertOrDecrease(start);

        while (heap.size > 0) {
            int node = heap.removeMin();
            if (node == target) break;

            int x = node % xCount;
            int y = node / xCount;

            if (x > 0) {
                int next = node - 1;
                int cost = horizontalCovered[y * horizontalWidth + x - 1] != 0
                        ? 0 : xs[x] - xs[x - 1];
                relax(node, next, cost, distance, position, heap);
            }
            if (x + 1 < xCount) {
                int next = node + 1;
                int cost = horizontalCovered[y * horizontalWidth + x] != 0
                        ? 0 : xs[x + 1] - xs[x];
                relax(node, next, cost, distance, position, heap);
            }
            if (y > 0) {
                int next = node - xCount;
                int cost = verticalCovered[(y - 1) * xCount + x] != 0
                        ? 0 : ys[y] - ys[y - 1];
                relax(node, next, cost, distance, position, heap);
            }
            if (y + 1 < yCount) {
                int next = node + xCount;
                int cost = verticalCovered[y * xCount + x] != 0
                        ? 0 : ys[y + 1] - ys[y];
                relax(node, next, cost, distance, position, heap);
            }
        }

        System.out.println(distance[target]);
    }

    static void relax(int from, int to, int cost, int[] distance, int[] position, MinHeap heap) {
        if (position[to] == -2) return;
        int candidate = distance[from] + cost;
        if (candidate < distance[to]) {
            distance[to] = candidate;
            heap.insertOrDecrease(to);
        }
    }

    static int unique(int[] values) {
        if (values.length == 0) return 0;
        int count = 1;
        for (int i = 1; i < values.length; i++) {
            if (values[i] != values[count - 1]) values[count++] = values[i];
        }
        return count;
    }
